import pandas as pd
import re

def assign_portion_size(food_name: str) -> float:
    """
    Maps a food item string to a standard adult portion size in grams
    based on dietary portion guidelines.
    """
    name = str(food_name).lower()

    # Oils, fats, spreads
    if any(k in name for k in ['oil', 'butter', 'margarine', 'lard', 'mayonnaise']):
        return 15.0

    # Nuts, seeds, chocolate, hard cheese
    if any(k in name for k in ['nut', 'almond', 'walnut', 'peanut', 'seed', 'chocolate', 'cheddar', 'parmesan']):
        return 30.0

    # Bread, cereal, dried fruit
    if any(k in name for k in ['bread', 'toast', 'slice', 'cereal', 'muesli', 'raisin', 'date', 'crisp']):
        return 40.0

    # Raw grains, pasta, flour
    if any(k in name for k in ['raw pasta', 'raw rice', 'oats', 'flour', 'quinoa', 'couscous', 'spaghetti']):
        return 75.0

    # Fresh fruit & vegetables
    if any(k in name for k in ['apple', 'banana', 'orange', 'pear', 'berry', 'tomato', 'broccoli', 'spinach', 'carrot']):
        return 80.0

    # Meats, poultry, tofu
    if any(k in name for k in ['chicken', 'beef', 'pork', 'lamb', 'steak', 'turkey', 'tofu', 'bacon']):
        return 100.0

    # Fish & seafood
    if any(k in name for k in ['salmon', 'tuna', 'cod', 'haddock', 'prawn', 'shrimp', 'fish']):
        return 120.0

    # Legumes & canned beans
    if any(k in name for k in ['chickpea', 'lentil', 'kidney bean', 'baked bean', 'black bean']):
        return 130.0

    # Yogurt & dairy products
    if any(k in name for k in ['yogurt', 'yoghurt', 'cottage cheese']):
        return 150.0

    # Cooked carb staples
    if any(k in name for k in ['cooked pasta', 'cooked rice', 'boiled potato', 'mashed potato']):
        return 180.0

    # Liquids / Milk
    if any(k in name for k in ['milk', 'juice', 'smoothie']):
        return 200.0

    # Default fallback portion for unspecified solid foods
    return 100.0

def process_nutrition_csv(input_filepath: str, output_filepath: str):
    df = pd.read_csv(input_filepath)

    # 1. Deduce food item column (matches 'food', 'item', 'name', or defaults to first column)
    food_col = next((c for c in df.columns if c.lower() in ['food', 'item', 'name', 'food_item', 'description']), df.columns[0])

    # 2. Add portion_size_g column
    df['portion_size_g'] = df[food_col].apply(assign_portion_size)

    # 3. Handle Unit Conversions & Per-Portion Computations
    # Scaled ratio factor: portion_size_g / 100.0
    scaling_factor = df['portion_size_g'] / 100.0

    numeric_cols = df.select_dtypes(include=['number']).columns.tolist()
    if 'portion_size_g' in numeric_cols:
        numeric_cols.remove('portion_size_g')

    for col in numeric_cols:
        col_lower = col.lower()

        # Identify milligram columns and generate a standardized gram equivalent column if requested
        if 'mg' in col_lower:
            # Convert base mg per 100g to g per 100g
            df[f"{col}_in_g"] = df[col] / 1000.0
            # Calculate absolute per-portion value in grams
            df[f"{col}_per_portion_g"] = (df[f"{col}_in_g"] * scaling_factor).round(4)
            # Calculate absolute per-portion value in milligrams
            df[f"{col}_per_portion_mg"] = (df[col] * scaling_factor).round(2)

        elif 'kcal' in col_lower or 'energy' in col_lower or 'calories' in col_lower:
            # Energy remains unchanged in units (kcal), simply scale by portion size
            df[f"{col}_per_portion"] = (df[col] * scaling_factor).round(1)

        else:
            # Standard gram-based macronutrients (protein, fat, carbs, fibre)
            df[f"{col}_per_portion_g"] = (df[col] * scaling_factor).round(2)

    df.to_csv(output_filepath, index=False)
    print(f"Processed dataset successfully saved to: {output_filepath}")

# Execution
process_nutrition_csv('cleaned_nutrition_dataset_per100g.csv', 'cleaned_nutrition_dataset_with_portions.csv')